mapper.select:
select bd.id, bd.parent_id, bd.dept_name, bd.dept_code, bd.category, (exists(select 1 from bedrock_dept bdh where bdh.parent_id = bd.id)) as hasChildren from bedrock_dept bd where bd.is_deleted = 0
and bd.parent_id = #{param.parentId}
and bd.category = #{param.category}
and bd.dept_name like concat('%',#{param.deptName},'%')
order by bd.sort,bd.create_time desc
